-- Фінальна перевірка рівня A1 · 30 завдань
do $$
declare v_aid uuid; v_payload jsonb;
begin
  select id into v_aid from public.assessments where slug = 'a1-final';
  if v_aid is null then raise exception 'Немає тесту a1-final'; end if;
  if exists (select 1 from public.assessment_items where id = 'a88f730c-2188-5ca7-b5e2-438db19362e6') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'curriculum_a1_v3: перевірку модуля оновлено під нові уроки — старі завдання');
  update public.assessments set description_ua = 'Кінець рівня (усі 13 модулів A1): 30 завдань на 4 навички. ~15 хв.' where id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + 100
   where assessment_id = v_aid and status = 'PUBLISHED' and order_index <= 100;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('a88f730c-2188-5ca7-b5e2-438db19362e6', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Я комунікабельна, люблю знайомитися з новими людьми.", "Три роки тому. Початок був дуже важкий.", "У тебе вийде, ти дуже працьовита!"]'::jsonb, 1, null, 'Prije tri godine. Početak je bio jako težak.', null, null, 'Прозвучало: «Prije tri godine. Početak je bio jako težak.» — «Три роки тому. Початок був дуже важкий.».', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b148221a-bdc9-5ae6-ab76-f48bf5b6919e', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Я застуджена, і в мене температура. Я була в лікаря.", "Доброго ранку, шефе. На жаль, я захворіла.", "Скріплю їх скріпкою й покладу в синю папку."]'::jsonb, 0, null, 'Prehlađena sam i imam temperaturu. Bila sam kod liječnika.', null, null, 'Прозвучало: «Prehlađena sam i imam temperaturu. Bila sam kod liječnika.» — «Я застуджена, і в мене температура. Я була в лікаря.».', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v1'),
  ('be82302b-d02f-5e63-b8b8-7d50c776e467', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, які в тебе цілі на наступний рік?", "Даріє, ти залишишся в Хорватії?", "Яка ваша спеціальність?"]'::jsonb, 1, null, 'Darja, hoćeš li ostati u Hrvatskoj?', null, null, 'Прозвучало: «Darja, hoćeš li ostati u Hrvatskoj?» — «Даріє, ти залишишся в Хорватії?».', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v1'),
  ('9367ba9e-9272-55b0-9539-0db19e49ac58', v_aid, 4, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Залізниця пускає замінний автобус перед вокзалом.", "Добре. До п’ятниці все буде готово.", "Можете купити одноразовий квиток у застосунку."]'::jsonb, 2, null, 'Možete kupiti jednokratnu kartu u aplikaciji.', null, null, 'Прозвучало: «Možete kupiti jednokratnu kartu u aplikaciji.» — «Можете купити одноразовий квиток у застосунку.».', (select id from public.lessons where id = '0ef458c5-53cf-530a-99cf-4ccd6e0132e5'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4cbc67b1-2ea9-55e9-848b-56c76b317e8a', v_aid, 5, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, як ти любиш проводити вихідні?", "Дашо, сьогодні субота. Розподілимо домашні справи?", "О котрій ти виходиш з дому?"]'::jsonb, 0, null, 'Dašo, kako voliš provesti vikend?', null, null, 'Прозвучало: «Dašo, kako voliš provesti vikend?» — «Дашо, як ти любиш проводити вихідні?».', (select id from public.lessons where id = '458b73de-d6b3-5bd3-98ad-c243a2fff03f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('f7b51ae2-3b6f-50bf-9f14-5c4778416bd9', v_aid, 6, 'A1', 'reading', 'understand', 'multiple_choice', 'Що п’ють люди?', 'Advent u Zagrebu', '["Пиво", "Сік", "Глінтвейн"]'::jsonb, 2, null, null, 'Advent u Zagrebu počinje krajem studenoga i traje do početka siječnja. Grad je pun svjetla, a na trgovima su male kućice s hranom i pićem. Ljudi piju kuhano vino i jedu fritule i kobasice. Na klizalištu se kližu djeca i odrasli. Svake godine dolazi puno turista iz cijelog svijeta.', 'Адвент у Загребі починається наприкінці листопада й триває до початку січня. Місто сповнене вогнів, а на площах — маленькі будиночки з їжею та напоями. Люди п’ють глінтвейн і їдять фрітуле та ковбаски. На ковзанці катаються діти й дорослі. Щороку приїжджає багато туристів з усього світу.', 'Текст «Адвент у Загребі». Правильна відповідь: «Глінтвейн».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('9d5e14ec-3407-5ee0-8680-597891030a54', v_aid, 7, 'A1', 'reading', 'understand', 'multiple_choice', 'З чим їсти млинці?', 'Recept: palačinke', '["Із сиром і шинкою", "З рибою", "З джемом, медом або шоколадом"]'::jsonb, 2, null, null, 'Trebate: dva jaja, pola litre mlijeka, dvjesto grama brašna, malo soli i ulja.
U zdjelu stavite jaja i mlijeko. Dodajte brašno i sol i dobro miješajte. Zagrijte tavu s malo ulja. Stavite malo smjese u tavu i pecite minutu sa svake strane. Palačinke jedite s pekmezom, medom ili čokoladom. Dobar tek!', 'Вам потрібно: два яйця, пів літра молока, двісті грамів борошна, трохи солі й олії.
У миску покладіть яйця й молоко. Додайте борошно й сіль і добре перемішайте. Розігрійте сковорідку з невеликою кількістю олії. Налийте трохи тіста на сковорідку й смажте хвилину з кожного боку. Млинці їжте з джемом, медом або шоколадом. Смачного!', 'Текст «Рецепт: млинці». Правильна відповідь: «З джемом, медом або шоколадом».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('8d63411a-fe4a-5ddb-88ea-5fa33216e6c9', v_aid, 8, 'A1', 'reading', 'understand', 'multiple_choice', 'Що вони роблять увечері?', 'Razglednica s otoka', '["Працюють", "Гуляють набережною", "Дивляться фільм"]'::jsonb, 1, null, null, 'Draga Marija,
pozdrav s Hvara! More je toplo i čisto, a plaže su prekrasne. Svaki dan se kupamo i jedemo svježu ribu. Navečer šetamo uz rivu. Grad je mali, ali ima puno ljudi. Vraćamo se u nedjelju trajektom. Jedva čekam da se vidimo!
Grli te Oksana', 'Дорога Маріє,
привіт із Хвару! Море тепле й чисте, а пляжі чудові. Щодня ми купаємося і їмо свіжу рибу. Увечері гуляємо набережною. Місто маленьке, але людей багато. Повертаємося в неділю поромом. Не можу дочекатися нашої зустрічі!
Обіймаю, Оксана', 'Текст «Листівка з острова». Правильна відповідь: «Гуляють набережною».', null, 'PUBLISHED', 'claude_assessment_v1'),
  ('2cc9ace4-2b06-524f-83d3-f3a658a0b177', v_aid, 9, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćemo li bojiti jaja?', '["Drži ovu tipku sa strane, bako.", "Hoćemo! Djeca će napraviti pisanice.", "Brzi vlak polazi u osam i petnaest."]'::jsonb, 1, null, 'Hoćemo li bojiti jaja?', null, null, 'Діалог «Великдень»: «Hoćemo li bojiti jaja?» (Будемо фарбувати яйця?) — «Hoćemo! Djeca će napraviti pisanice.» (Будемо! Діти зроблять писанки.).', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v1'),
  ('8624fa2c-2868-53c5-a80a-eb708f1f498d', v_aid, 10, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Oprostite, gdje mogu poništiti kartu?', '["Poništač je kod vrata, žuti aparat.", "Odlično! Glavni glumac je bio fantastičan.", "Žive, i vukovi i risovi, ali su jako plahi."]'::jsonb, 0, null, 'Oprostite, gdje mogu poništiti kartu?', null, null, 'Діалог «У трамваї»: «Oprostite, gdje mogu poništiti kartu?» (Перепрошую, де можна прокомпостувати квиток?) — «Poništač je kod vrata, žuti aparat.» (Компостер біля дверей, жовтий апарат.).', (select id from public.lessons where id = '0ef458c5-53cf-530a-99cf-4ccd6e0132e5'), 'PUBLISHED', 'claude_assessment_v1'),
  ('bd9fd840-f864-5fbf-b5a6-8476253a1ffc', v_aid, 11, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Joj, ispričavam se! Smeta li vam jako?', '["S drugog, ali danas kasni dvadeset minuta.", "Malo, jer dijete spava.", "Temperatura zraka do trideset osam."]'::jsonb, 1, null, 'Joj, ispričavam se! Smeta li vam jako?', null, null, 'Діалог «Голосна музика»: «Joj, ispričavam se! Smeta li vam jako?» (Ой, вибачте! Вам дуже заважає?) — «Malo, jer dijete spava.» (Трохи, бо дитина спить.).', (select id from public.lessons where id = 'a42b9121-2ec0-5064-909b-f59f315b3c4a'), 'PUBLISHED', 'claude_assessment_v1'),
  ('762e931e-6a4a-519f-a522-b1c5b7146b43', v_aid, 12, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koja je najveća prednost života ovdje?', '["Jesmo, a poslije je Pozdrav Suncu svijetlio u svim bojama.", "Ovjeru možeš napraviti kod javnog bilježnika, blizu je.", "Sigurnost i more. A nedostatak — birokracija!"]'::jsonb, 2, null, 'Koja je najveća prednost života ovdje?', null, null, 'Діалог «Залишитися чи ні?»: «Koja je najveća prednost života ovdje?» (Яка найбільша перевага життя тут?) — «Sigurnost i more. A nedostatak — birokracija!» (Безпека й море. А недолік — бюрократія!).', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v1'),
  ('e57f9275-b3ed-5b3b-87fb-20dcbe0cec86', v_aid, 13, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Pametno. Što si zadnje objavila?', '["Jedan dan je plaćen. Trebaš moje odobrenje.", "U trećem b. Tvoja razrednica je učiteljica Ana.", "Objavu o tečaju hrvatskog, tražim partnera za razgovor."]'::jsonb, 2, null, 'Pametno. Što si zadnje objavila?', null, null, 'Діалог «Новини й коментарі»: «Pametno. Što si zadnje objavila?» (Розумно. Що ти останнє опублікувала?) — «Objavu o tečaju hrvatskog, tražim partnera za razgovor.» (Допис про курси хорватської, шукаю партнера для розмов.).', (select id from public.lessons where id = '4edd1556-f088-5d14-8f59-529b35747609'), 'PUBLISHED', 'claude_assessment_v1'),
  ('a3f6421d-cfe9-53eb-9a9f-46db1be59974', v_aid, 14, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Rado! Što ćemo tamo raditi?', '["U osam, kod mene. Možeš doći s pratnjom.", "Zdravstvenu iskaznicu i popis lijekova.", "Radimo roštilj u vrtu, a u nedjelju idemo planinariti."]'::jsonb, 2, null, 'Rado! Što ćemo tamo raditi?', null, null, 'Діалог «Плани на суботу»: «Rado! Što ćemo tamo raditi?» (Залюбки! Що ми там робитимемо?) — «Radimo roštilj u vrtu, a u nedjelju idemo planinariti.» (Смажимо барбекю в саду, а в неділю йдемо в гори.).', (select id from public.lessons where id = '458b73de-d6b3-5bd3-98ad-c243a2fff03f'), 'PUBLISHED', 'claude_assessment_v1'),
  ('b959eac9-a9be-5dd0-9938-a54214f0c4af', v_aid, 15, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koliko traje školski sat?', '["Nakon naplatne kućice idite obilaznicom.", "Četrdeset pet minuta, a veliki odmor dvadeset minuta.", "Predivno! Slušali smo morske orgulje na rivi."]'::jsonb, 1, null, 'Koliko traje školski sat?', null, null, 'Діалог «Перший день у школі»: «Koliko traje školski sat?» (Скільки триває урок?) — «Četrdeset pet minuta, a veliki odmor dvadeset minuta.» (Сорок п’ять хвилин, а велика перерва — двадцять хвилин.).', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v1'),
  ('d0403df1-ae6b-5c68-976e-296e350b4d9a', v_aid, 16, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jeste li već bili kod nas kao pacijent?', '["Прошу, сідайте. Опишіть мені симптоми.", "Ні, я тут уперше.", "Три дні в мене болить горло й температура."]'::jsonb, 1, null, null, 'Liječnica: Izvolite, sjednite. Opišite mi simptome.
Luka: Tri dana me boli grlo i imam temperaturu.
Liječnica: Jeste li već bili kod nas kao pacijent?
Luka: Nisam, prvi put sam ovdje.
Liječnica: Imate li dopunsko osiguranje?
Luka: Nemam. Koliko je participacija?', 'Liječnica: Прошу, сідайте. Опишіть мені симптоми.
Luka: Три дні в мене болить горло й температура.
Liječnica: Ви вже були в нас як пацієнт?
Luka: Ні, я тут уперше.
Liječnica: У вас є додаткове страхування?
Luka: Немає. Скільки доплата?', 'Діалог «В кабінеті»: «Jeste li već bili kod nas kao pacijent?» — «Nisam, prvi put sam ovdje.», тобто «Ні, я тут уперше.».', (select id from public.lessons where id = '08e31e8b-f8f7-5a80-89ed-093bc68dae03'), 'PUBLISHED', 'claude_assessment_v1'),
  ('d5b66e80-2ba7-5560-902a-cdc231ef0b6c', v_aid, 17, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?', '["Добрий день, я шукаю постійну роботу.", "У мене немає посвідчення на навантажувач.", "Можете, тільки повідомте нам."]'::jsonb, 1, null, null, 'Marko: Dobar dan, tražim stalan posao.
Savjetnica: Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?
Marko: Nemam vozačku za viličar.
Savjetnica: Zavod vam može platiti tečaj.
Marko: Super. A do tada? Trebam li honorarni posao?
Savjetnica: Možete, samo nam javite.', 'Marko: Добрий день, я шукаю постійну роботу.
Savjetnica: Є вакансія комірника. Є умови, яким ви не відповідаєте?
Marko: У мене немає посвідчення на навантажувач.
Savjetnica: Центр може оплатити вам курси.
Marko: Чудово. А до того? Мені шукати підробіток?
Savjetnica: Можете, тільки повідомте нам.', 'Діалог «У центрі зайнятості»: «Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?» — «Nemam vozačku za viličar.», тобто «У мене немає посвідчення на навантажувач.».', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v1'),
  ('4563814f-53b3-5de4-8e51-4c66cab08d92', v_aid, 18, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li opera ili balet?', '["На Шалаті? Там улітку фестиваль.", "Давай. А в суботу концерт мого улюбленого гурту.", "Балет. Квитки ще продаються."]'::jsonb, 2, null, null, 'Daša: Luka, u HNK-u je u petak premijera nove predstave.
Luka: Je li opera ili balet?
Daša: Balet. Ulaznice su još u prodaji.
Luka: Može. A u subotu je koncert mog omiljenog benda.
Daša: Na Šalati? Tamo je ljeti festival.
Luka: Da, otvoreni koncert. Pjevač je odličan uživo.', 'Daša: Луко, у Національному театрі в п’ятницю прем’єра нової вистави.
Luka: Це опера чи балет?
Daša: Балет. Квитки ще продаються.
Luka: Давай. А в суботу концерт мого улюбленого гурту.
Daša: На Шалаті? Там улітку фестиваль.
Luka: Так, концерт просто неба. Співак чудовий наживо.', 'Діалог «Куди підемо?»: «Je li opera ili balet?» — «Balet. Ulaznice su još u prodaji.», тобто «Балет. Квитки ще продаються.».', (select id from public.lessons where id = '631c7f59-de43-5081-adb7-77bdf23ce805'), 'PUBLISHED', 'claude_assessment_v1'),
  ('6e02e901-c57e-5569-b402-9af57f073fda', v_aid, 19, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imamo li još vlažnih maramica?', '["Яку туш? Їх сто видів.", "Немає, купи дві пачки. І мені туш.", "Будь-яку чорну. А тобі потрібні нові бритви."]'::jsonb, 1, null, null, 'Luka: Idem u drogeriju. Što trebamo?
Darja: Gel za tuširanje, deterdžent i omekšivač.
Luka: Imamo li još vlažnih maramica?
Darja: Nemamo, kupi dva pakiranja. I meni maskaru.
Luka: Koju maskaru? Ima ih sto vrsta.
Darja: Bilo koju crnu. A tebi trebaju nove britvice.', 'Luka: Я йду в дрогерію. Що нам треба?
Darja: Гель для душу, засіб для прання й кондиціонер.
Luka: У нас ще є вологі серветки?
Darja: Немає, купи дві пачки. І мені туш.
Luka: Яку туш? Їх сто видів.
